    18	  @Test
    19	  void parsesAndRendersPointers() {
    20	    PointerValuesPointers.Pointer root = PointerValuesPointers.parse("");
    21	    PointerValuesPointers.Pointer pointer = PointerValuesPointers.parse("/a~1b/~0/");
    22	
    23	    assertEquals("", root.toString());
    24	    assertEquals("/a~1b/~0/", PointerValuesPointers.render(pointer));
    25	    assertEquals(PointerValuesPointers.parse("/same"), PointerValuesPointers.parse("/same"));
    26	    assertThrows(PointerValuesPointers.MalformedPointerException.class,
    27	        () -> PointerValuesPointers.parse("bad"));
    28	    assertThrows(PointerValuesPointers.MalformedPointerException.class,
    29	        () -> PointerValuesPointers.parse("/~2"));
    30	  }
    31	
    32	  @Test
    33	  void resolvesImplementationsAndContainers() {
    34	    ImmutablePointerValues.Leaf first = leaf("first");
    35	    ImmutablePointerValues.Leaf second = leaf("second");
    36	    ImmutablePointerValues.Branch root = branch(first, second);
    37	
    38	    assertEquals("first", PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/child/value")));
    39	    assertEquals("second", PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/children/1/value")));
    40	    assertEquals("second", PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/named/key/value")));
    41	    assertEquals("first", PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/optional/value")));
    42	    assertNull(PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/nullable")));
    43	    assertEquals("second", PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/array/0/value")));
    44	    assertInstanceOf(int[].class, PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/primitiveArray")));
    45	  }
    46	
    47	  @Test
    48	  void updatesOnlyTheAddressedPath() {
    49	    ImmutablePointerValues.Leaf first = leaf("first");
    50	    ImmutablePointerValues.Leaf second = leaf("second");
    51	    ImmutablePointerValues.Branch root = branch(first, second);
    52	
    53	    ImmutablePointerValues.Branch updated = (ImmutablePointerValues.Branch) PointerValuesPointers.update(
    54	        root,
    55	        PointerValuesPointers.parse("/children/0/value"),
    56	        value -> "changed");
    57	
    58	    assertNotSame(root, updated);
    59	    assertSame(root.child(), updated.child());
    60	    assertNotSame(root.children().get(0), updated.children().get(0));
    61	    assertSame(root.children().get(1), updated.children().get(1));
    62	    assertSame(root.named(), updated.named());
    63	    assertEquals(leaf("changed"), updated.children().get(0));
    64	
    65	    UnaryOperator<String> equalReplacement = value -> new String("first");
    66	    Object unchanged = PointerValuesPointers.update(
    67	        root,
    68	        PointerValuesPointers.parse("/child/value"),
    69	        equalReplacement);
    70	    assertSame(root, unchanged);
    71	  }
