    73	  @Test
    74	  void distinguishesMissesAndTypeErrors() {
    75	    ImmutablePointerValues.Branch root = branch(leaf("first"), leaf("second"));
    76	
    77	    assertThrows(PointerValuesPointers.PointerMissException.class, () -> PointerValuesPointers.resolve(
    78	        root, PointerValuesPointers.parse("/missing")));
    79	    assertThrows(PointerValuesPointers.PointerTypeException.class, () -> PointerValuesPointers.resolve(
    80	        root, PointerValuesPointers.parse("/children/01")));
    81	    assertThrows(PointerValuesPointers.PointerMissException.class, () -> PointerValuesPointers.resolve(
    82	        root, PointerValuesPointers.parse("/children/99")));
    83	    assertThrows(PointerValuesPointers.PointerMissException.class, () -> PointerValuesPointers.resolve(
    84	        root, PointerValuesPointers.parse("/nullable/value")));
    85	    assertThrows(PointerValuesPointers.PointerTypeException.class, () -> PointerValuesPointers.update(
    86	        root, PointerValuesPointers.parse("/set"), value -> value));
    87	    assertThrows(PointerValuesPointers.PointerTypeException.class, () -> PointerValuesPointers.update(
    88	        root, PointerValuesPointers.parse("/derived"), value -> value));
    89	    assertThrows(PointerValuesPointers.PointerTypeException.class, () -> PointerValuesPointers.update(
    90	        root, PointerValuesPointers.parse("/child"), value -> "wrong"));
    91	    assertThrows(IllegalArgumentException.class, () -> PointerValuesPointers.resolve(
    92	        "wrong", PointerValuesPointers.parse("")));
    93	  }
