    95	  private static ImmutablePointerValues.Leaf leaf(String value) {
    96	    return ImmutablePointerValues.Leaf.builder().value(value).build();
    97	  }
    98	
    99	  private static ImmutablePointerValues.Branch branch(
   100	      ImmutablePointerValues.Leaf first, ImmutablePointerValues.Leaf second) {
   101	    Map<String, PointerValues.Node> named = new LinkedHashMap<>();
   102	    named.put("key", second);
   103	    return ImmutablePointerValues.Branch.builder()
   104	        .child(first)
   105	        .addAllChildren(Arrays.asList(first, second))
   106	        .putAllNamed(named)
   107	        .optional(Optional.of(first))
   108	        .nullable(null)
   109	        .array(second)
   110	        .primitiveArray(1, 2)
   111	        .addSet(second)
   112	        .build();
   113	  }
